function drawMap(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.scale(zoom,zoom);ctx.translate(-canvas.width/2,-canvas.height/2);for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=state.grid[y][x],pxx=x*TILE,py=y*TILE;drawTerrain(t.terrain,pxx,py,x,y);if((x+y)%2===0&&t.terrain!=='water')px(pxx+1,py+TILE-2,TILE-2,1,'#243b32');if(t.building)drawBuilding(t.building.type,pxx,py,selectedTile?.x===x&&selectedTile?.y===y);else if(selectedTile?.x===x&&selectedTile?.y===y){px(pxx+1,py+1,TILE-2,2,'#ffe693');px(pxx+1,py+TILE-3,TILE-2,2,'#ffe693');px(pxx+1,py+1,2,TILE-2,'#ffe693');px(pxx+TILE-3,py+1,2,TILE-2,'#ffe693');}}ctx.restore();}
function research(tech){if(state.resources.knowledge<tech.cost){toast('Falta saber para esta descoberta.');return;}state.resources.knowledge-=tech.cost;state.techs.push(tech.id);addLog(tech.effect);renderUI();save(true);toast(`Nova descoberta: ${tech.name}!`);}
function build(type,x,y){const b=buildings[type],tile=state.grid[y][x];if(!b)return;if(tile.terrain==='water'){toast('Não é possível construir sobre a água.');return;}if(tile.building){toast('Este terreno já está ocupado.');return;}if(state.year<eras[b.era].start){toast('Essa construção pertence a uma era futura.');return;}if(b.tech&&!state.techs.includes(b.tech)){toast('Pesquise a tecnologia necessária primeiro.');return;}for(const [k,v] of Object.entries(b.cost))if(state.resources[k]<v){toast(`Recursos insuficientes: ${resources[k].name.toLowerCase()}.`);return;}for(const[k,v]of Object.entries(b.cost))state.resources[k]-=v;tile.building={type,level:1};selectedBuild=null;selectedTile={x,y};addLog(`${b.name} erguido em nosso reino.`);renderUI();drawMap();save(true);toast(`${b.name} construído!`);}
function placeClick(e){const rect=canvas.getBoundingClientRect();const sx=(e.clientX-rect.left)/rect.width*canvas.width,sy=(e.clientY-rect.top)/rect.height*canvas.height;const x=Math.floor((canvas.width/2+(sx-canvas.width/2)/zoom)/TILE),y=Math.floor((canvas.height/2+(sy-canvas.height/2)/zoom)/TILE);if(x<0||x>=W||y<0||y>=H)return;const t=state.grid[y][x];if(selectedBuild&&!t.building){build(selectedBuild,x,y);return;}selectedTile={x,y};if(t.building){selectedBuild=null;$('#mapTip').textContent=`${buildings[t.building.type].name} · terreno ${x+1}, ${y+1}`;}else if(selectedBuild)$('#mapTip').textContent=`${buildings[selectedBuild].name} selecionado → clique num terreno`;else $('#mapTip').textContent=t.terrain==='water'?'Curso d’água · não edificável':'Terreno livre · escolha uma construção';renderUI();drawMap();}
function step(years){if(paused)return;const oldEra=eraIndex();state.year=Math.min(99999,state.year+years);state.playSeconds+=years/speeds[speedIndex];const p=production();for(const [k,v]of Object.entries(p))state.resources[k]=Math.max(0,Math.min(999999,(state.resources[k]||0)+v*years));state.resources.knowledge=Math.min(999999,state.resources.knowledge+years*.025);const capacity=state.grid.flat().reduce((a,t)=>a+(t.building?(buildings[t.building.type].capacity||0):0),0);const foodOkay=state.resources.food>0;const housed=state.population<capacity;const growth=(foodOkay&&housed&&state.happiness>20)?state.population*.00015*years:0;state.population=Math.max(1,Math.min(capacity||1,state.population+growth));if(!foodOkay){state.population=Math.max(1,state.population-years*.003);state.happiness=Math.max(5,state.happiness-years*.04);}else state.happiness=Math.min(100,Math.max(35,state.happiness+years*.001));const newEra=eraIndex();if(newEra>oldEra){for(let i=oldEra+1;i<=newEra;i++){state.resources.knowledge+=7;addLog(`Uma nova era começa: ${eras[i].name.toLowerCase()}! +7 saber.`);}toast(`A humanidade entrou na era ${eras[newEra].name.toLowerCase()}!`);}if(state.year>=2026&&state.events.indexOf('future-reached')<0){state.events.push('future-reached');addLog('O reino alcançou a era moderna. O futuro está em suas mãos!');toast('Uma nova era da humanidade começa!');}if(state.playSeconds%12<years/speeds[speedIndex])save(true);}
function gameLoop(now){const dt=Math.min(.25,(now-lastFrame)/1000);lastFrame=now;if(!paused)step(dt*speeds[speedIndex]);if(now%250<18){renderUI();}requestAnimationFrame(gameLoop);}
function showModal(){const modal=$('#modal');$('#modalTitle').textContent='Como jogar';$('#modalContent').innerHTML='<p>Você é o senhor destas terras. Comece com um acampamento e conduza seu povo da Idade da Pedra até o futuro.</p><p><b>1.</b> Escolha uma construção no painel da direita.<br><b>2.</b> Clique num terreno livre no mapa para erguê-la.<br><b>3.</b> Produza recursos, aumente sua população e pesquise tecnologias quando uma nova era chegar.<br><b>4.</b> Use os controles de velocidade. Seu progresso é salvo automaticamente neste dispositivo.</p><p>Alimento sustenta o povo; cabanas aumentam o limite populacional. Cada edifício produz recursos a cada ano.</p>';modal.classList.add('show');}
function resetGame(){if(!confirm('Começar um novo reino? O progresso atual será apagado.'))return;localStorage.removeItem(SAVE_KEY);state=freshState();logItems=[];addLog('Uma tribo se estabeleceu no vale. Sua história começa.');selectedBuild=null;selectedTile=null;speedIndex=0;paused=false;$('#pauseBtn').innerHTML='Ⅱ &nbsp; PAUSAR';renderUI();drawMap();save(true);toast('Um novo reino começa!');}
canvas.addEventListener('click',placeClick);$('#zoomIn').onclick=()=>{zoom=Math.min(1.35,zoom+.1);drawMap();};$('#zoomOut').onclick=()=>{zoom=Math.max(1,zoom-.1);drawMap();};$('#pauseBtn').onclick=()=>{paused=!paused;$('#pauseBtn').innerHTML=paused?'▶ &nbsp; RETOMAR':'Ⅱ &nbsp; PAUSAR';toast(paused?'O tempo parou.':'A história continua.');};$('#speedBtn').onclick=()=>{speedIndex=(speedIndex+1)%speeds.length;$('#speedBtn').innerHTML=`⏩ &nbsp; ${speedNames[speedIndex]}`;toast(`Velocidade: ${speedNames[speedIndex]}`);};$('#saveBtn').onclick=()=>save();$('#resetBtn').onclick=resetGame;$('#helpBtn').onclick=showModal;$('#modalClose').onclick=()=>$('#modal').classList.remove('show');$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')$('#modal').classList.remove('show');});$('#soundToggle').onclick=()=>{const el=$('#soundToggle');el.textContent=el.textContent.includes('OFF')?'♫ SOM: ON':'♫ SOM: OFF';toast('O som ambiente será adicionado em breve.');};
const hadSave=load();logItems=Array.isArray(state.events)?state.events.filter(e=>e&&typeof e==='object'&&'year'in e):[];if(!logItems.length)addLog(hadSave?'Seu reino retomou a jornada.':'Uma tribo se estabeleceu no vale. Sua história começa.');renderUI();drawMap();if(!hadSave){save(true);setTimeout(showModal,700);}requestAnimationFrame(gameLoop);
</script></body></html>

